module full_adder_struct(a, b, cin, sum, cout);
  input a;
  wire a;
  input b;
  wire b;
  input cin;
  wire cin;
  output cout;
  wire cout;
  wire s1;
  wire s2;
  wire s3;
  output sum;
  wire sum;
  wire u1_y;
  wire u2_y;
  wire u3_y;
  wire u4_y;
  wire u5_y;
  xor_gate u1 (
    .a(a),
    .b(b),
    .y(s1)
  );
  xor_gate u2 (
    .a(s1),
    .b(cin),
    .y(u2_y)
  );
  and_gate u3 (
    .a(a),
    .b(b),
    .y(s2)
  );
  and_gate u4 (
    .a(s1),
    .b(cin),
    .y(s3)
  );
  or_gate u5 (
    .a(s2),
    .b(s3),
    .y(u5_y)
  );
  assign cout = u5_y;
  assign sum = u2_y;
  assign u1_y = s1;
  assign u3_y = s2;
  assign u4_y = s3;
endmodule

