module top(clk, rst, a, b, cin, op, sum, cout, psum, pcout, sy, ovf);
  input [7:0] a;
  wire [7:0] a;
  input [7:0] b;
  wire [7:0] b;
  input cin;
  wire cin;
  input clk;
  wire clk;
  output cout;
  wire cout;
  input op;
  wire op;
  output ovf;
  wire ovf;
  output pcout;
  wire pcout;
  output [7:0] psum;
  wire [7:0] psum;
  input rst;
