  wire [7:0] sum;
  output [7:0] sy;
  wire [7:0] sy;
  wire u_adder_cout;
  wire [7:0] u_adder_sum;
  wire u_addsub_ovf;
  wire [7:0] u_addsub_y;
  wire u_pipe_cout;
  wire [7:0] u_pipe_sum;
  adder8 u_adder (
    .a(a),
    .b(b),
    .cin(cin),
    .cout(u_adder_cout),
    .sum(u_adder_sum)
  );
  add_sub_shared u_addsub (
    .a(a),
    .b(b),
    .op(op),
    .ovf(u_addsub_ovf),
    .y(u_addsub_y)
  );
  adder8_pipelined u_pipe (
