    .b(b),
    .cin(cin),
    .clk(clk),
    .cout(u_pipe_cout),
    .rst(rst),
    .sum(u_pipe_sum)
  );
  assign cout = u_adder_cout;
  assign ovf = u_addsub_ovf;
  assign pcout = u_pipe_cout;
  assign psum = u_pipe_sum;
  assign sum = u_adder_sum;
  assign sy = u_addsub_y;
